import{_ as n,o as s,c as e,a2 as l}from"./chunks/framework.EUByU7Iq.js";const b=JSON.parse('{"title":"第八章 民事责任","description":"","frontmatter":{"title":"第八章 民事责任","date":"2021-02-16T00:00:00.000Z","categories":["法律","民法典"],"tags":["法律","民法典"]},"headers":[],"relativePath":"blogs/CC/dibazhang：minshizeren.md","filePath":"blogs/CC/第八章：民事责任.md"}'),p={name:"blogs/CC/dibazhang：minshizeren.md"};function r(i,a,t,o,h,c){return s(),e("div",null,[...a[0]||(a[0]=[l(`<h3 id="第一百七十六条" tabindex="-1">第一百七十六条 <a class="header-anchor" href="#第一百七十六条" aria-label="Permalink to &quot;第一百七十六条&quot;">​</a></h3><p>民事主体依照法律规定或者按照当事人约定，履行民事义务，承担民事责任。</p><h3 id="第一百七十七条" tabindex="-1">第一百七十七条 <a class="header-anchor" href="#第一百七十七条" aria-label="Permalink to &quot;第一百七十七条&quot;">​</a></h3><p>二人以上依法承担按份责任，能够确定责任大小的，各自承担相应的责任；难以确定责任大小的，平均承担责任。</p><h3 id="第一百七十八条" tabindex="-1">第一百七十八条 <a class="header-anchor" href="#第一百七十八条" aria-label="Permalink to &quot;第一百七十八条&quot;">​</a></h3><p>二人以上依法承担连带责任的，权利人有权请求部分或者全部连带责任人承担责任。 连带责任人的责任份额根据各自责任大小确定；难以确定责任大小的，平均承担责任。实际承担责任超过自己责任份额的连带责任人，有权向其他连带责任人追偿。 连带责任，由法律规定或者当事人约定。</p><h3 id="第一百七十九条" tabindex="-1">第一百七十九条 <a class="header-anchor" href="#第一百七十九条" aria-label="Permalink to &quot;第一百七十九条&quot;">​</a></h3><p>承担民事责任的方式主要有：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>（一）停止侵害；</span></span>
<span class="line"><span>（二）排除妨碍；</span></span>
<span class="line"><span>（三）消除危险；</span></span>
<span class="line"><span>（四）返还财产；</span></span>
<span class="line"><span>（五）恢复原状；</span></span>
<span class="line"><span>（六）修理、重作、更换；</span></span>
<span class="line"><span>（七）继续履行；</span></span>
<span class="line"><span>（八）赔偿损失；</span></span>
<span class="line"><span>（九）支付违约金；</span></span>
<span class="line"><span>（十）消除影响、恢复名誉；</span></span>
<span class="line"><span>（十一）赔礼道歉。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>法律规定惩罚性赔偿的，依照其规定。 本条规定的承担民事责任的方式，可以单独适用，也可以合并适用。</p><h3 id="第一百八十条" tabindex="-1">第一百八十条 <a class="header-anchor" href="#第一百八十条" aria-label="Permalink to &quot;第一百八十条&quot;">​</a></h3><p>因不可抗力不能履行民事义务的，不承担民事责任。法律另有规定的，依照其规定。 不可抗力是不能预见、不能避免且不能克服的客观情况。</p><h3 id="第一百八十一条" tabindex="-1">第一百八十一条 <a class="header-anchor" href="#第一百八十一条" aria-label="Permalink to &quot;第一百八十一条&quot;">​</a></h3><p>因正当防卫造成损害的，不承担民事责任。 正当防卫超过必要的限度，造成不应有的损害的，正当防卫人应当承担适当的民事责任。</p><h3 id="第一百八十二条" tabindex="-1">第一百八十二条 <a class="header-anchor" href="#第一百八十二条" aria-label="Permalink to &quot;第一百八十二条&quot;">​</a></h3><p>因紧急避险造成损害的，由引起险情发生的人承担民事责任。 危险由自然原因引起的，紧急避险人不承担民事责任，可以给予适当补偿。 紧急避险采取措施不当或者超过必要的限度，造成不应有的损害的，紧急避险人应当承担适当的民事责任。</p><h3 id="第一百八十三条" tabindex="-1">第一百八十三条 <a class="header-anchor" href="#第一百八十三条" aria-label="Permalink to &quot;第一百八十三条&quot;">​</a></h3><p>因保护他人民事权益使自己受到损害的，由侵权人承担民事责任，受益人可以给予适当补偿。没有侵权人、侵权人逃逸或者无力承担民事责任，受害人请求补偿的，受益人应当给予适当补偿。</p><h3 id="第一百八十四条" tabindex="-1">第一百八十四条 <a class="header-anchor" href="#第一百八十四条" aria-label="Permalink to &quot;第一百八十四条&quot;">​</a></h3><p>因自愿实施紧急救助行为造成受助人损害的，救助人不承担民事责任。</p><h3 id="第一百八十五条" tabindex="-1">第一百八十五条 <a class="header-anchor" href="#第一百八十五条" aria-label="Permalink to &quot;第一百八十五条&quot;">​</a></h3><p>侵害英雄烈士等的姓名、肖像、名誉、荣誉，损害社会公共利益的，应当承担民事责任。</p><h3 id="第一百八十六条" tabindex="-1">第一百八十六条 <a class="header-anchor" href="#第一百八十六条" aria-label="Permalink to &quot;第一百八十六条&quot;">​</a></h3><p>因当事人一方的违约行为，损害对方人身权益、财产权益的，受损害方有权选择请求其承担违约责任或者侵权责任。</p><h3 id="第一百八十七条" tabindex="-1">第一百八十七条 <a class="header-anchor" href="#第一百八十七条" aria-label="Permalink to &quot;第一百八十七条&quot;">​</a></h3><p>民事主体因同一行为应当承担民事责任、行政责任和刑事责任的，承担行政责任或者刑事责任不影响承担民事责任；民事主体的财产不足以支付的，优先用于承担民事责任。</p>`,26)])])}const u=n(p,[["render",r]]);export{b as __pageData,u as default};
